WITH base AS (SELECT id, full_name, email, dept_id, manager_id, job_title, salary, hire_date, is_remote, level, LOWER(full_name) AS full_name_lower, COALESCE(job_title, 'OTHER') AS job_title_clean FROM employees WHERE hire_date >= TO_DATE('2023-05-24') AND hire_date >= '2025-07-01') SELECT * FROM (SELECT dept_id, job_title, salary FROM base) src PIVOT (MAX(salary) FOR job_title IN ('Director', 'Designer', 'Engineer'))
